"import bs4\n\nwith open('tests/workday/Systems Software Engineer - New College Grad 2026.htm', 'r', encoding='utf-8') as f:\n    soup = bs4.BeautifulSoup(f.read(), 'html.parser')\n\nprint(\"=== DETAILED INPUT INSPECTION ===\")\nfor inp in soup.find_all(['input', 'textarea', 'button', 'select']):\n    elem_id = inp.get('id', '')\n    name = inp.get('name', '')\n    auto_id = inp.get('data-automation-id', '')\n    aria_label = inp.get('aria-label', '')\n    txt = inp.get_text(strip=True)\n    \n    # find closest label or field container\n    container = inp.find_parent(attrs={'data-automation-id': True}) or inp.find_parent('fieldset') or inp.find_parent('div')\n    c_autoid = container.get('data-automation-id', '') if container else ''\n    \n    # find label\n    lbl = inp.find_previous('label')\n    lbl_text = lbl.get_text(strip=True) if lbl else ''\n    \n    print(f\"[{inp.name}] id='{elem_id}' name='{name}' autoId='{auto_id}' aria='{aria_label}' text='{txt}' | container_autoId='{c_autoid}' | label='{lbl_text}'\")\n"